Object.assign(Z_STRINGS.en, {"stg.directBold": "No inbound to Iran?", "stg.directText": "Use BackPack Direct mode instead of a reverse tunnel: Setup Iran → Direct → pick a carrier (udp, quic, pck, sni, xdi, spoof). Iran dials out so no inbound port is needed, and forwarded ports work the same. The tunnel port can be pinned to one address (IP:port) in the wizard."});
Object.assign(Z_STRINGS.fa, {"stg.directBold": "به ایران inbound نمی‌رسد؟", "stg.directText": "به‌جای تانل معکوس از حالت Direct در BackPack استفاده کن: Setup Iran → Direct → یک carrier انتخاب کن (udp، quic، pck، sni، xdi، spoof). ایران dial-out می‌کند پس پورت ورودی لازم نیست و پورت‌های فوروارد همان‌طور کار می‌کنند. پورت تانل را می‌توان در ویزارد به یک آدرس پین کرد (IP:port)."});
Object.assign(Z_STRINGS.zh, {"stg.directBold": "伊朗收不到入站？", "stg.directText": "改用 BackPack Direct 模式而非反向隧道：Setup Iran → Direct → 选择 carrier（udp、quic、pck、sni、xdi、spoof）。伊朗主动外拨，无需入站端口，转发端口用法相同。隧道端口可在向导里绑定到单个地址（IP:port）。"});
Object.assign(Z_STRINGS.ru, {"stg.directBold": "Входящие в Иран не проходят?", "stg.directText": "Возьми режим Direct вместо обратного туннеля: Setup Iran → Direct → выбери carrier (udp, quic, pck, sni, xdi, spoof). Иран звонит наружу, входящий порт не нужен, проброс портов работает так же. Порт туннеля можно привязать к одному адресу (IP:port) в визарде."});

Object.assign(Z_STRINGS.en, {"chg.v1130": "— BackPack v1.8.2 support", "chg.v1130a_lead": "New UDP transport:", "chg.v1130a": "plain UDP joins the tunnel transport list (raw, lowest overhead) alongside KCP/QUIC.", "chg.v1130b_lead": "Direct mode covered:", "chg.v1130b": "setup guide and docs now explain Direct mode (Iran dials out, no inbound port) with its 6 carriers, Link Test recommendations, WSS certificate needs, and IP:port tunnel pinning."});
Object.assign(Z_STRINGS.fa, {"chg.v1130": "— پشتیبانی BackPack v1.8.2", "chg.v1130a_lead": "transport جدید UDP:", "chg.v1130a": "UDP ساده به لیست transportهای تانل اضافه شد (خام، کمترین overhead) در کنار KCP/QUIC.", "chg.v1130b_lead": "پوشش حالت Direct:", "chg.v1130b": "راهنمای نصب و داکس حالا حالت Direct را توضیح می‌دهند (ایران dial-out می‌کند، بدون inbound) با 6 carrier آن، پیشنهادهای Link Test، نیاز گواهی WSS و پین تانل به IP:port."});
Object.assign(Z_STRINGS.zh, {"chg.v1130": "——支持 BackPack v1.8.2", "chg.v1130a_lead": "新增 UDP 传输：", "chg.v1130a": "纯 UDP 加入隧道传输列表（原始、开销最低），与 KCP/QUIC 并列。", "chg.v1130b_lead": "Direct 模式已覆盖：", "chg.v1130b": "搭建指南和文档现已说明 Direct 模式（伊朗主动外拨、无需入站端口）及其 6 种 carrier、Link Test 推荐、WSS 证书需求和 IP:port 隧道绑定。"});
Object.assign(Z_STRINGS.ru, {"chg.v1130": "— поддержка BackPack v1.8.2", "chg.v1130a_lead": "Новый UDP-транспорт:", "chg.v1130a": "Обычный UDP в списке транспортов туннеля (сырой, минимальный оверхед) рядом с KCP/QUIC.", "chg.v1130b_lead": "Режим Direct покрыт:", "chg.v1130b": "Гайд и доки теперь объясняют режим Direct (Иран звонит наружу, без входящего порта) с его 6 carrier, рекомендациями Link Test, нуждой WSS в сертификате и привязкой туннеля к IP:port."});

Object.assign(Z_STRINGS.en, {"chg.v1131": "— White-hat rounds 5–7 hardening", "chg.v1131a_lead": "Abuse bounds:", "chg.v1131a": "user creation is rate-limited (120/hour) and capped at 10,000 users, so a leaked bot token can no longer flood the database or rotate the audit trail away; restores take a safety snapshot first.", "chg.v1131b_lead": "Stricter builders:", "chg.v1131b": "AI action arguments are strictly typed (no \"false\"-string flips), volume totals clamp at the documented cap, and link/config builders re-validate hosts, keys and filenames at the last gate. Shadowsocks links are now spec-correct URL-safe base64 — re-copy the link if a strict client complains."});
Object.assign(Z_STRINGS.fa, {"chg.v1131": "— سخت‌سازی راندهای 5 تا 7 کلاه‌سفید", "chg.v1131a_lead": "سقف‌های سوءاستفاده:", "chg.v1131a": "ساخت کاربر ریت‌لیمیت (120 در ساعت) و سقف 10,000 کاربر دارد، پس توکن بات لو رفته دیگر نمی‌تواند دیتابیس را پر کند یا لاگ audit را بچرخاند؛ restoreها اول اسنپ‌شات امنیتی می‌گیرند.", "chg.v1131b_lead": "بیلدرهای سخت‌گیرانه‌تر:", "chg.v1131b": "آرگومان‌های اکشن AI اکیداً تایپ می‌شوند (چرخش رشته‌ای \"false\" نیست)، مجموع حجم روی سقف مستند clamp می‌شود و بیلدرهای لینک/کانفیگ هاست‌ها، کلیدها و نام فایل‌ها را در آخرین گیت دوباره اعتبارسنجی می‌کنند. لینک‌های Shadowsocks حالا base64 استاندارد URL-safe هستند — اگر کلاینت سخت‌گیری شکایت کرد لینک را دوباره کپی کن."});
Object.assign(Z_STRINGS.zh, {"chg.v1131": "——白帽第 5–7 轮加固", "chg.v1131a_lead": "滥用上限：", "chg.v1131a": "用户创建限流（每小时 120）且上限 10,000 用户，泄露的机器人令牌无法再淹没数据库或轮转掉审计日志；恢复前先做安全快照。", "chg.v1131b_lead": "更严格的构建器：", "chg.v1131b": "AI 动作参数严格定型（无 \"false\" 字符串翻转），流量总计按文档上限钳制，链接/配置构建器在最后一道关口重新校验主机、密钥和文件名。Shadowsocks 链接现为规范的 URL-safe base64——若严格客户端报错请重新复制链接。"});
Object.assign(Z_STRINGS.ru, {"chg.v1131": "— Харденинг white-hat раундов 5–7", "chg.v1131a_lead": "Ограничения злоупотреблений:", "chg.v1131a": "Создание юзеров ограничено (120/час) и потолком 10 000 — утёкший токен бота больше не зальёт базу и не провернёт аудит; ресторы сначала делают страховочный снапшот.", "chg.v1131b_lead": "Более строгие билдеры:", "chg.v1131b": "Аргументы AI-действий строго типизированы (без переворотов строкой \"false\"), суммарный трафик ограничен задокументированным потолком, а билдеры ссылок/конфигов перепроверяют хосты, ключи и имена файлов на последнем рубеже. Ссылки Shadowsocks теперь spec-корректный URL-safe base64 — если строгий клиент ругается, скопируй ссылку заново."});

